lab.solution:
import pickle

def score_job(job):
    return {'course': job['course'], 'total': sum(job['points'])}

job = {'course': 'PY-102', 'points': (4, 6)}
received = pickle.loads(pickle.dumps(job))
result = score_job(received)
assert received == job
assert result == {'course': 'PY-102', 'total': 10}
assert job == {'course': 'PY-102', 'points': (4, 6)}
print(received == job, result)
